def solve_v2(test_input):
    h, w = len(test_input), len(test_input[0])

    # Find frame boundaries
    frame_color = None
    frame_top = frame_bottom = frame_left = frame_right = None

    for r in range(h):
        for c in range(w):
            val = test_input[r][c]
            if val != 0:
                if frame_color is None:
                    frame_color = val
                frame_top = min(frame_top, r) if frame_top is not None else r
                frame_bottom = max(frame_bottom, r) if frame_bottom is not None else r
                frame_left = min(frame_left, c) if frame_left is not None else c
                frame_right = max(frame_right, c) if frame_right is not None else c

    if frame_color is None:
        return [[0]*w for _ in range(h)]

    inter_h = frame_bottom - frame_top - 1
    inter_w = frame_right - frame_left - 1

    print(f"Frame: {frame_color}, interior: {inter_h}x{inter_w}")

    # Collect and deduplicate consecutive values
    scatter_seq = []
    for r in range(h):
        for c in range(w):
            val = test_input[r][c]
            if val != 0 and val != frame_color:
                scatter_seq.append(val)

    condensed = [scatter_seq[0]] if scatter_seq else []
    for v in scatter_seq[1:]:
        if v != condensed[-1]:
            condensed.append(v)
    print(f"Condensed seq: {condensed}")

    # Place one condensed item per COLUMN, cycling through condensed sequence
    result = {}
    for c in range(inter_w):
        for r in range(inter_h):
            idx = r + c * inter_h  # Linear index
            item = condensed[idx % len(condensed)]
            if item not in result:
                result[item] = []
            result[item].append(r)

    print("Items and their rows:", result)

    # Build output
    output_interior = [[0]*inter_w for _ in range(inter_h)]
    for item, rows in result.items():
        for r in rows:
            output_interior[r][(r+inter_h)//len(condensed)%inter_w] = item  # Approximate column

    # Build full output with frame
    output = []
    for r in range(frame_top, frame_bottom + 1):
        row = []
        for c in range(frame_left, frame_right + 1):
            dr = r - (frame_top + 1)
            dc = c - (frame_left + 1)
            if 0 <= dr < inter_h and 0 <= dc < inter_w:
                output.append(row)
            row.append(frame_color if not (0 <= dr < inter_h and 0 <= dc < inter_w) else 0)
        output.append(row)

    return output

