def solve_puzzle_full(test_input):
    h, w = len(test_input), len(test_input[0])

    # Find frame
    frame_color = None
    frame_top = frame_bottom = frame_left = frame_right = None

    for r in range(h):
        for c in range(w):
            val = test_input[r][c]
            if val != 0:
                if frame_color is None:
                    frame_color = val
                frame_top = min(frame_top, r) if frame_top is not None else r
                frame_bottom = max(frame_bottom, r) if frame_bottom is not None else r
                frame_left = min(frame_left, c) if frame_left is not None else c
                frame_right = max(frame_right, c) if frame_right is not None else c

    inter_h = frame_bottom - frame_top - 1
    inter_w = frame_right - frame_left - 1

    print(f"Frame: {frame_color}, Interior: {inter_h}x{inter_w}")

    # Collect scatter pixels (non-zero, non-frame-color) in raster order
    scatter_seq = []
    for r in range(h):
        for c in range(w):
            val = test_input[r][c]
            if val != 0 and val != frame_color:
                scatter_seq.append(val)

    # Condense (remove consecutive duplicates)
    condensed = []
    if scatter_seq:
        condensed = [scatter_seq[0]]
        for v in scatter_seq[1:]:
            if v != condensed[-1]:
                condensed.append(v)

    print(f"Condensed sequence: {condensed} (len={len(condensed)})")

    # Fill interior ONE CELL PER ITEM
    result_interior = [[0]*inter_w for _ in range(inter_h)]
    idx = 0
    for r in range(inter_h):
        for c in range(inter_w):
            if idx < len(condensed):
                result_interior[r][c] = condensed[idx]
            idx += 1

    # Build full output with frame
    output = []
    for r in range(frame_top, frame_bottom + 1):
        row = []
        for c in range(frame_left, frame_right + 1):
            dr = r - frame_top
            dc = c - frame_left
            if dr < inter_h and dc < inter_w:
                row.append(result_interior[dr][dc])
            else:
                row.append(frame_color)
        output.append(row)

    return output

